'use strict';
(() => {
 const KEY='techpath.personal.v1',base=['localhost','127.0.0.1'].includes(location.hostname)?location.origin:'http://127.0.0.1:4173';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const uid=()=>crypto.randomUUID(),empty=()=>({schema:KEY,chats:[],profile:'Mình là An, mới tốt nghiệp IT, chuyên ngành Information Systems, đang tìm hướng đi và công việc phù hợp. Mình thích game (đặc biệt Valorant), nhạc game/anime và J-pop, và học ngoại ngữ. Tiếng Anh TOEIC LR 895; Nhật/Trung mới bắt đầu. Ở đây mình muốn tâm sự về cuộc sống và cảm xúc, được lắng nghe trước khi nhận lời khuyên. Đừng mặc định chuyện gì cũng liên quan đến công việc hay học SQL. Hãy hỏi khi chưa hiểu, đừng suy đoán thay mình.',route:'gemini:ag/gemini-3.8-flash-low',style:'listen'});
 let data=empty(),unlocked=false,selected='',search='',busy=false,uploading=false,focused=false,controller=null,notice='',storageBroken=false,geminis=[],catalogLoaded=false;
 const IMAGE_LIMIT=384*1024;
 function validImages(value){if(value===undefined)return [];if(!Array.isArray(value)||value.length>2)throw new Error('Tối đa 2 ảnh mỗi tin nhắn.');return value.map(i=>{if(typeof i?.url!=='string'||i.url.length>Math.ceil(IMAGE_LIMIT/3)*4+32||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(i.url))throw new Error('Ảnh sao lưu không hợp lệ hoặc quá lớn.');return {url:i.url,name:typeof i.name==='string'?i.name.slice(0,100):'Ảnh đính kèm'};});}
 const $=s=>document.querySelector('#personal-root '+s),current=()=>data.chats.find(c=>c.id===selected);
 function validate(raw){
  if(raw?.schema!==KEY||!Array.isArray(raw.chats)||raw.chats.length>500)throw new Error('Không đúng bản sao lưu không gian riêng.');
  const s=empty(),str=(x,n)=>typeof x==='string'?x.slice(0,n):'';
  s.profile=str(raw.profile,2000);s.route=['local','light','codex','gemini-cli'].includes(raw.route)||/^(gemini|router):/.test(raw.route||'')?raw.route:'local';s.style=['listen','reflect','plan'].includes(raw.style)?raw.style:'listen';
  if(s.route==='gemini-cli')s.route='gemini:ag/gemini-3.8-flash-low';
  s.chats=raw.chats.filter(c=>c&&/^[a-f0-9-]{36}$/i.test(c.id)&&Array.isArray(c.messages)&&c.messages.length<=1000).map(c=>({id:c.id,title:str(c.title,100)||'Cuộc trò chuyện',draft:str(c.draft,6000),draftImages:validImages(c.draftImages),archived:!!c.archived,messages:c.messages.filter(m=>m&&['user','assistant'].includes(m.role)&&typeof m.text==='string').map(m=>({role:m.role,text:str(m.text,30000),images:m.role==='user'?validImages(m.images):[],failed:!!m.failed,at:str(m.at,50),provider:str(m.provider,200)}))}));return s;
 }
 try{const raw=localStorage.getItem(KEY);if(raw)data=validate(JSON.parse(raw));}catch{storageBroken=true;notice='Dữ liệu riêng chưa đọc được. Hãy xuất bản gốc trước khi nhập bản khôi phục.';}
 function save(){if(storageBroken)return false;try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch{notice='Chưa lưu được: bộ nhớ đầy hoặc bị chặn. Xuất sao lưu để giữ nội dung.';return false;}}
 function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 const options=()=>`<option value="local">Local AI · model đang tải</option><option value="gemini:ag/gemini-3.8-flash-low">Gemini Flash · Antigravity</option><option value="light">Tiết kiệm · techpath-light</option><option value="codex">Codex · GPT-6.1 Sol (chữ)</option>${geminis.filter(m=>m.id!=='ag/gemini-3.8-flash-low').map(m=>`<option value="${m.id.startsWith('gh/')?'router':'gemini'}:${esc(m.id)}">${esc(m.label||m.id)}${m.vision?' · ảnh':''}</option>`).join('')}`;
 const imageMarkup=images=>(images||[]).map(i=>`<button type="button" data-personal-view-image class="personal-image-link" aria-label="Mở ảnh ${esc(i.name)}"><img src="${esc(i.url)}" alt="${esc(i.name)}" loading="lazy"></button>`).join('');
 const previews=()=>`<div class="personal-attachments">${(current()?.draftImages||[]).map((i,n)=>`<figure><img src="${esc(i.url)}" alt="${esc(i.name)}"><figcaption>${esc(i.name)}</figcaption><button type="button" class="personal-remove-image" data-personal-remove-image="${n}" aria-label="Bỏ ảnh ${esc(i.name)}" title="Bỏ ảnh">×</button></figure>`).join('')}</div>`;
 function messages(){const c=current();return c?.messages.length?c.messages.map(m=>`<article class="personal-message ${m.role==='user'?'mine':''} ${m.failed?'incomplete':''}"><small>${m.role==='user'?'Bạn':esc(m.provider||'AI')}${m.failed?' · Chưa hoàn tất':''}</small>${m.images?.length?`<div class="personal-message-images">${imageMarkup(m.images)}</div>`:''}<div>${esc(m.text)}</div></article>`).join(''):`<div class="personal-welcome"><span class="eyebrow">MỘT KHOẢNG RIÊNG</span><h2>Hôm nay, bạn muốn nói về điều gì?</h2><p>Có thể là chuyện nhỏ trong ngày, một điều đang vướng, hay đơn giản là muốn nói ra.</p><div class="actions"><button class="button secondary" data-personal-prompt="Mình muốn kể một chuyện, trước hết hãy lắng nghe nhé.">Mình muốn được lắng nghe</button><button class="button secondary" data-personal-prompt="Có một việc khiến mình phân vân. Hãy cùng mình gỡ rối từng chút.">Cùng gỡ một chuyện</button></div></div>`;}
 function list(){return data.chats.filter(c=>!c.archived&&c.title.toLowerCase().includes(search.toLowerCase())).slice().reverse().map(c=>`<button class="personal-thread ${c.id===selected?'selected':''}" data-personal-thread="${c.id}">${esc(c.title)}</button>`).join('')||'<p class="subtle">Chưa có cuộc trò chuyện.</p>';}
 function gate(){return `<section class="card personal-gate"><span class="eyebrow">KHÔNG GIAN RIÊNG</span><h1>Một khoảng để trò chuyện.</h1><p>Lịch sử cá nhân được lưu riêng với việc học, trên trình duyệt và địa chỉ app này.</p><p class="subtle">Lối vào được giấu cho kín đáo; dữ liệu chưa được mã hóa hay khóa bằng mật khẩu.</p><button class="button" data-personal-unlock>Mở không gian trò chuyện →</button><a class="resource" href="#settings">← Về cài đặt</a></section>`;}
 function view(){
  if(!unlocked)return `<div id="personal-root">${gate()}</div>`;
  const c=current();return `<div id="personal-root"><div class="personal-heading"><div><span class="eyebrow">KHÔNG GIAN RIÊNG</span><h1>Ở đây, cứ nói điều bạn muốn.</h1></div><div class="actions"><button class="button secondary small" data-personal-focus aria-pressed="${focused}">${focused?'↙ Thu gọn':'⛶ Mở rộng'}</button><a class="button secondary small" href="#settings">Rời không gian riêng ↗</a></div></div><div class="personal-layout"><aside class="personal-sidebar"><button class="button full" data-personal-new>＋ Cuộc trò chuyện mới</button><input id="personal-search" type="search" placeholder="Tìm cuộc trò chuyện…" aria-label="Tìm cuộc trò chuyện" value="${esc(search)}"><div class="personal-threads">${list()}</div><details><summary>AI nên biết về mình</summary><p class="save-meta">Bạn tự chọn điều muốn chia sẻ. Phần này được gửi cùng mỗi tin nhắn đến AI đang chọn.</p><textarea id="personal-profile" maxlength="2000" placeholder="Ví dụ: Mình thích được lắng nghe trước khi nhận lời khuyên…">${esc(data.profile)}</textarea></details><details><summary>Lưu trữ & sao lưu riêng</summary><p class="save-meta">Không nằm trong file sao lưu học tập. PC/laptop và bản local/Site cần xuất/nhập riêng.</p><div class="actions"><button class="button secondary small" data-personal-export>Xuất JSON</button><button class="button secondary small" data-personal-import>Nhập JSON</button></div><button class="text-link" data-personal-restore>Khôi phục các cuộc đã cất</button></details></aside><section class="personal-chat"><header class="personal-chat-head"><strong>${esc(c?.title||'Cuộc trò chuyện mới')}</strong><div class="actions"><button class="text-link" data-personal-rename ${!c?'disabled':''}>Đổi tên</button><button class="text-link" data-personal-archive ${!c?'disabled':''}>Cất cuộc chat</button><button class="button danger small" data-personal-delete ${!c||busy?'disabled':''}>Xóa cuộc chat</button></div></header><div class="personal-controls"><label>Trò chuyện với<select id="personal-route">${options()}</select></label><label>Cách trò chuyện<select id="personal-style"><option value="listen">Lắng nghe</option><option value="reflect">Cùng gỡ rối</option><option value="plan">Lên kế hoạch</option></select></label><button class="button secondary small" data-personal-refresh>Làm mới AI</button></div><p class="save-meta personal-routing"></p><div class="personal-messages">${messages()}</div><div class="personal-compose">${previews()}<p id="personal-status" role="status">${esc(notice)}</p><label class="sr-only" for="personal-input">Tin nhắn riêng</label><textarea id="personal-input" maxlength="6000" rows="3" placeholder="Viết điều đang ở trong đầu bạn…">${esc(c?.draft||'')}</textarea><div class="actions"><button class="button secondary" data-personal-attach ${busy||uploading?'disabled':''} title="Chọn ảnh, hoặc dán/kéo ảnh vào ô chat">＋ Ảnh</button><input type="file" id="personal-images" class="sr-only" accept="image/jpeg,image/png,image/webp" multiple aria-label="Chọn ảnh đính kèm"><button class="button" data-personal-send ${busy?'disabled':''}>${busy?'Đang trả lời…':'Gửi tin nhắn ↑'}</button><button class="button secondary" data-personal-stop ${!busy?'hidden':''}>Dừng</button><span class="save-meta">Ctrl + Enter để gửi · Không tự gửi lại khi lỗi</span></div></div></section></div></div>`;
 }
 function paintMessages(){const box=$('.personal-messages');if(box){box.innerHTML=messages();box.scrollTop=box.scrollHeight;}const s=$('#personal-status');if(s)s.textContent=notice;const b=$('[data-personal-send]');if(b){b.disabled=busy||uploading||storageBroken;b.textContent=busy?'Đang trả lời…':'Gửi tin nhắn ↑';}for(const name of ['delete','archive','rename']){const action=$('[data-personal-'+name+']');if(action)action.disabled=!current()||busy||uploading||storageBroken;}const attach=$('[data-personal-attach]');if(attach)attach.disabled=busy||uploading||storageBroken;const stop=$('[data-personal-stop]');if(stop)stop.hidden=!busy;}
 function routeNote(){const el=$('.personal-routing');if(el)el.textContent=(data.route==='local'?'Chỉ dùng model đang tải trong LM Studio trên máy này. Ảnh cần model có vision.':data.route==='codex'||data.route==='gemini-cli'?'Kết nối CLI này hiện chỉ nhận chữ.':'Tin nhắn, ảnh và hồ sơ đã điền được gửi đến provider đang chọn qua 9Router; dùng hạn mức của tài khoản kết nối.')+' Giữ tối đa 12 tin gần nhất và 2 ảnh lịch sử trong ngữ cảnh.';}
 function mount(){document.body.classList.toggle('personal-focus',unlocked&&focused&&!!document.querySelector('#personal-root'));if(!document.querySelector('#personal-root')){unlocked=false;controller?.abort();return;}window.TechPathTutor?.close?.();if(!unlocked)return;const r=$('#personal-route');if(![...r.options].some(o=>o.value===data.route)&&/^(gemini|router):/.test(data.route))r.add(new Option(data.route.slice(data.route.indexOf(':')+1)+' · cần làm mới danh mục',data.route));r.value=data.route;$('#personal-style').value=data.style;routeNote();paintMessages();}
 function redraw(){const root=document.querySelector('#personal-root');if(root){root.outerHTML=view();mount();}}
 function newChat(){const c={id:uid(),title:'Cuộc trò chuyện mới',messages:[],draft:'',draftImages:[],archived:false};data.chats.push(c);selected=c.id;save();return c;}
 async function refresh(){notice='Đang đọc trạng thái AI…';paintMessages();try{const provider=data.route==='local'?'local':data.route==='codex'?'codex':'router';const r=await fetch(base+'/api/tutor/status?provider='+provider,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw new Error('Bộ kết nối chưa sẵn sàng.');const s=await r.json();geminis=s.router?.personalModels||(s.router?.models||[]).filter(m=>/gemini/i.test(m.id));catalogLoaded=!!s.router?.connected;if(data.route==='gemini-cli'){const a=await fetch(base+'/api/personal/gemini-status',{signal:AbortSignal.timeout(5000)});const st=await a.json();notice=st.message;}else notice=s[provider]?.message||s.message;const select=$('#personal-route');if(select){select.innerHTML=options();if(![...select.options].some(o=>o.value===data.route))select.add(new Option(data.route.slice(data.route.indexOf(':')+1),data.route));select.value=data.route;}}catch{notice='Chưa kết nối được máy này. Mở Start TechPath; nếu Site bị chặn, dùng bản local và chuyển lịch sử bằng sao lưu riêng.';}paintMessages();}
 async function attachImages(files){
  if(busy||uploading||storageBroken)return;
  const chosen=Array.from(files||[]);if(!chosen.length)return;
  const c=current()||newChat(),previous=c.draftImages||[];
  if(previous.length+chosen.length>2){notice='Mỗi tin nhắn tối đa 2 ảnh. Bỏ bớt ảnh trước khi thêm.';paintMessages();return;}
  uploading=true;notice='Đang chuẩn bị ảnh trên thiết bị…';paintMessages();
  try{
   const encoded=[];
   for(const file of chosen){
    if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Chọn JPEG, PNG hoặc WebP dưới 10 MB mỗi ảnh.');
    const bitmap=await createImageBitmap(file);
    try{
     if(bitmap.width*bitmap.height>40000000)throw new Error('Ảnh quá lớn. Chọn ảnh dưới 40 megapixel.');
     const canvas=document.createElement('canvas'),scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));
     const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(bitmap,0,0,canvas.width,canvas.height);
     let url='';for(const quality of [.86,.72,.58,.44]){url=canvas.toDataURL('image/jpeg',quality);if(url.length<=Math.ceil(IMAGE_LIMIT/3)*4+23)break;}
     encoded.push(...validImages([{url,name:file.name.slice(0,100)||'Ảnh đính kèm'}]));
    }finally{bitmap.close();}
   }
   c.draftImages=[...previous,...encoded];if(!save()){c.draftImages=previous;throw new Error('Bộ nhớ trình duyệt đầy. Xuất sao lưu hoặc xóa cuộc chat cũ trước khi thêm ảnh.');}
   notice='Đã thêm ảnh. Ảnh chỉ được gửi khi bạn bấm Gửi tin nhắn.';
  }catch(error){notice=error.message||'Không đọc được ảnh.';}
  finally{uploading=false;redraw();}
 }
 async function send(){if(busy||uploading||storageBroken)return;const input=$('#personal-input'),text=input.value.trim(),images=current()?.draftImages||[];if(!text&&!images.length)return;let c=current()||newChat();
  const history=c.messages.filter(m=>!m.failed).slice(-12).map(m=>({role:m.role,text:m.text,images:m.images||[]}));let remaining=2;for(const m of history.slice().reverse()){m.images=remaining?m.images.slice(-remaining):[];remaining-=m.images.length;}
  const withImages=images.length||history.some(m=>m.images.length);if(withImages&&(data.route==='codex'||data.route==='light'||data.route==='gemini-cli'||(data.route.startsWith('router:')&&!geminis.find(m=>m.id===data.route.slice(7))?.vision))){notice='Chọn Gemini, Copilot GPT-4.1 / GPT-4o hoặc Local AI có vision để gửi ảnh.';paintMessages();return;}
  const previous=structuredClone(c);
  c.messages.push({role:'user',text,images,at:new Date().toISOString()});c.draft='';c.draftImages=[];if(c.title==='Cuộc trò chuyện mới')c.title=text.slice(0,55)||'Trò chuyện bằng ảnh';input.value='';busy=true;controller=new AbortController();notice='Đang kết nối…';
  const answer={role:'assistant',text:'',provider:data.route,failed:true,at:new Date().toISOString()};c.messages.push(answer);if(!save()){Object.assign(c,previous);busy=false;controller=null;redraw();return;}redraw();
  try{const provider=data.route==='local'?'local':data.route==='codex'?'codex':data.route==='gemini-cli'?'gemini-cli':'router';const status=await fetch(base+'/api/tutor/status?provider='+(provider==='gemini-cli'?'local':provider),{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(12000)])});const connection=await status.json();if(!status.ok||!connection.token)throw new Error('Bộ kết nối chưa sẵn sàng.');
   const response=await fetch(base+'/api/personal/chat',{method:'POST',headers:{'Content-Type':'application/json','X-TechPath-Token':connection.token},body:JSON.stringify({provider,model:data.route==='light'?'techpath-light':/^(gemini|router):/.test(data.route)?data.route.slice(data.route.indexOf(':')+1):undefined,prompt:text,images,history,profile:data.profile,style:data.style}),signal:AbortSignal.any([controller.signal,AbortSignal.timeout(240000)])});
   if(!response.ok){const e=await response.json();throw new Error(e.error||'Chưa gửi được tin nhắn.');}
   let buffer='',done=false;const decoder=new TextDecoder(),reader=response.body.getReader();
   const consume=line=>{if(!line.trim())return;const event=JSON.parse(line);if(event.type==='error')throw new Error(event.text);if(event.type==='delta'){answer.text+=event.text;notice='Đang trả lời…';paintMessages();}if(event.type==='done'){answer.text=event.text;answer.provider=event.provider+' · '+(event.model||'');answer.failed=false;done=true;}};
   try{while(true){const part=await reader.read();buffer+=decoder.decode(part.value||new Uint8Array(),{stream:!part.done});let i;while((i=buffer.indexOf('\n'))>=0){consume(buffer.slice(0,i));buffer=buffer.slice(i+1);}if(part.done)break;}if(buffer.trim())consume(buffer);}finally{await reader.cancel().catch(()=>{});reader.releaseLock();}
   if(!done)throw new Error('Kết nối ngắt trước khi AI trả lời xong.');notice='Đã lưu cuộc trò chuyện trên thiết bị này.';
  }catch(e){notice=controller.signal.aborted?'Đã dừng. Không tự gửi lại.':e.message;if(!answer.text)answer.text='Chưa nhận được phản hồi. Bạn có thể sửa tin nhắn và gửi khi sẵn sàng.';}
  finally{busy=false;controller=null;save();paintMessages();}
 }
 document.addEventListener('input',e=>{if(!e.target.closest('#personal-root'))return;if(e.target.id==='personal-profile'){data.profile=e.target.value;save();}if(e.target.id==='personal-input'){const c=current()||newChat();c.draft=e.target.value;save();for(const name of ['delete','archive','rename']){const action=$('[data-personal-'+name+']');if(action)action.disabled=busy||uploading||storageBroken;}}if(e.target.id==='personal-search'){search=e.target.value;$('.personal-threads').innerHTML=list();}});
 document.addEventListener('change',e=>{if(e.target.id==='personal-images'){attachImages(e.target.files);e.target.value='';return;}if(e.target.id==='personal-route'||e.target.id==='personal-style'){if(busy||uploading){notice='Chờ trả lời hoặc xử lý ảnh xong trước khi đổi.';redraw();return;}data[e.target.id==='personal-route'?'route':'style']=e.target.value;save();routeNote();}});
 document.addEventListener('keydown',e=>{if(e.target.id==='personal-input'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();send();}});
 document.addEventListener('paste',e=>{if(!e.target.closest('#personal-root .personal-compose'))return;const files=Array.from(e.clipboardData?.files||[]).filter(f=>f.type.startsWith('image/'));if(files.length){e.preventDefault();attachImages(files);}});
 document.addEventListener('dragover',e=>{if(e.target.closest('#personal-root')&&Array.from(e.dataTransfer?.types||[]).includes('Files')){e.preventDefault();}});
 document.addEventListener('drop',e=>{if(!e.target.closest('#personal-root'))return;e.preventDefault();attachImages(e.dataTransfer?.files);});
 document.addEventListener('click',async e=>{const b=e.target.closest('#personal-root button');if(!b)return;
  if(b.hasAttribute('data-personal-stop')){controller?.abort();return;}
  if(b.hasAttribute('data-personal-export')){download('techpath-private-'+new Date().toISOString().slice(0,10)+'.json',storageBroken?localStorage.getItem(KEY):JSON.stringify(data,null,2));return;}
  if(b.hasAttribute('data-personal-unlock')){unlocked=true;selected=data.chats.findLast(c=>!c.archived)?.id||'';location.hash='notebook';redraw();if(!catalogLoaded)await refresh();return;}
  if(b.hasAttribute('data-personal-view-image')){const image=b.querySelector('img'),dialog=document.createElement('dialog');dialog.className='personal-image-dialog';const close=document.createElement('button');close.className='button secondary';close.textContent='Đóng ảnh ×';close.onclick=()=>dialog.close();const large=document.createElement('img');large.src=image.src;large.alt=image.alt;dialog.append(close,large);dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();return;}
  if(busy||uploading){notice='Chờ AI trả lời hoặc xử lý ảnh xong trước.';paintMessages();return;}
  if(b.dataset.personalPrompt){$('#personal-input').value=b.dataset.personalPrompt;$('#personal-input').focus();return;}
  if(b.hasAttribute('data-personal-focus')){focused=!focused;redraw();return;}
  if(b.hasAttribute('data-personal-attach')){$('#personal-images').click();return;}
  if(b.dataset.personalRemoveImage!==undefined&&current()){current().draftImages.splice(Number(b.dataset.personalRemoveImage),1);save();notice='Đã bỏ ảnh đính kèm.';redraw();return;}
  if(b.hasAttribute('data-personal-delete')&&current()){const c=current();if(!confirm('Xóa vĩnh viễn cuộc chat “'+c.title+'” trên trình duyệt này?'))return;const old=data.chats;data.chats=old.filter(item=>item.id!==c.id);if(!save()){data.chats=old;paintMessages();return;}selected=data.chats.findLast(item=>!item.archived)?.id||'';notice='Đã xóa cuộc chat trên trình duyệt này.';redraw();return;}
  if(b.hasAttribute('data-personal-new')){newChat();redraw();}
  if(b.dataset.personalThread){selected=b.dataset.personalThread;notice='';redraw();}
  if(b.hasAttribute('data-personal-send'))await send();
  if(b.hasAttribute('data-personal-refresh'))await refresh();
  if(b.hasAttribute('data-personal-login')){notice='Đang mở đăng nhập…';paintMessages();try{const r=await fetch(base+'/api/tutor/status?provider=local',{signal:AbortSignal.timeout(12000)}),st=await r.json();const response=await fetch(base+'/api/personal/gemini-login',{method:'POST',headers:{'X-TechPath-Token':st.token},signal:AbortSignal.timeout(10000)}),body=await response.json();notice=body.message||body.error;}catch{notice='Mở Setup-GeminiChat.cmd trong thư mục TechPath để đăng nhập.';}paintMessages();}
  if(b.hasAttribute('data-personal-rename')&&current()){const title=prompt('Tên cuộc trò chuyện',current().title);if(title?.trim()){current().title=title.trim().slice(0,100);save();redraw();}}
  if(b.hasAttribute('data-personal-archive')&&current()){current().archived=true;selected='';save();redraw();}
  if(b.hasAttribute('data-personal-restore')){data.chats.forEach(c=>c.archived=false);save();redraw();}
  if(b.hasAttribute('data-personal-import')){const f=document.createElement('input');f.type='file';f.accept='.json';f.onchange=async()=>{const file=f.files[0];if(!file)return;try{if(file.size>25000000)throw new Error('Chọn file dưới 25 MB.');const next=validate(JSON.parse(await file.text()));if(!confirm('Nhập sẽ thay thế toàn bộ lịch sử riêng trên thiết bị này. App sẽ tải bản sao hiện tại trước. Tiếp tục?'))return;download('techpath-private-before-import.json',storageBroken?localStorage.getItem(KEY):JSON.stringify(data));data=next;storageBroken=false;selected=data.chats.findLast(c=>!c.archived)?.id||'';save();notice='Đã nhập lịch sử riêng.';redraw();}catch(error){notice=error.message;paintMessages();}};f.click();}
 });
 window.PersonalSpace={view,gate:()=>`<div id="personal-root">${gate()}</div>`,mount};
})();
